{% set services = filter_values('service_name') %}

{% if services %}
  {% set has_darkkitchen = 'Дарккитчен' in services %}
  {% set has_cafe = 'Кафе' in services %}
  {% set has_bakery = 'Пекарня' in services %}

  {% set service_filter %}
    1 = 1
    {% if has_darkkitchen and has_cafe and has_bakery %}
      AND darkkitchen_closed = 1
      AND cafebakery_production_closed = 3
    {% elif has_darkkitchen and has_cafe %}
      AND darkkitchen_closed = 1
      AND cafebakery_production_closed = 1
    {% elif has_darkkitchen and has_bakery %}
      AND darkkitchen_closed = 1
      AND cafebakery_production_closed = 2
    {% elif has_cafe and has_bakery %}
      AND darkkitchen_closed = 0
      AND cafebakery_production_closed = 3
    {% elif has_cafe %}
      AND darkkitchen_closed = 0
      AND cafebakery_production_closed = 1
    {% elif has_bakery %}
      AND darkkitchen_closed = 0
      AND cafebakery_production_closed = 2
    {% elif has_darkkitchen %}
      AND darkkitchen_closed = 1
      AND cafebakery_production_closed IS NULL
    {% endif %}
  {% endset %}
{% else %}
{% set service_filter = '(cafebakery_production_closed IS NOT NULL OR darkkitchen_closed <> 0)' %}
{% endif %}
COUNT(DISTINCT 
    IF(order_status = 'Успешно завершен'
      AND {{ service_filter  }}
      AND wait_time + collection_time >= 15
      {% if filter_values('id_service', remove_filter=True) %}
    	  and id_service IN {{ filter_values('id_service', remove_filter=True)|where_in }}
    	{% else %}
    	  and 1=1
    	{% endif %}
      , id_order, NULL))

