count(
	distinct 
		if(
			order_status = 'Успешно завершен'
            AND 
(
(id_service = 3 AND id_source = 80 AND order_type = 14 --это внутренний заказ от кухни, и время статуса Готов позже конца слота
AND date_status_10 > date_supply_untill)
OR 
(id_service = 3 AND (id_source <> 80 OR order_type <> 14) --это самовывоз, и время статуса Готов позже начала слота
AND date_status_10 > date_supply)
OR 
(id_service <> 3 --это не самовывоз и не кухня, и заказ оформлен позже дедлайна по сборке (связанный), и время сборки > нормативного времени сборки
AND date_order >= (date_supply_untill - coalesce(sla_delivery_time_all, 0) * 60)
AND collection_time_all > sla_collection_time_all)
OR 
(id_service <> 3 --это не самовывоз и не кухня, и в заказе есть позиции ДаркКитчен, и время сборки > нормативного времени сборки
AND darkkitchen_closed > 0
AND collection_time_all > sla_collection_time_all)
OR 
(id_service <> 3 --это не самовывоз, в заказе нет ДК, заказ оформлен до дедлайна по сборке, и окончание сборки позже дедлайна
AND (darkkitchen_closed = 0 or darkkitchen_closed is null)
AND date_order < (date_supply_untill - coalesce(sla_delivery_time_all, 0) * 60)
AND coalesce(date_set_cell, date_f_status_3_5) > (date_supply_untill - coalesce(sla_delivery_time_all, 0) * 60))
)
-- условия для скорости сборки дкп
      AND {{ service_filter  }}
			{% if filter_values('id_service', remove_filter=True) %}
			  and id_service IN {{ filter_values('id_service', remove_filter=True)|where_in }}
			{% else %}
			  and 1=1
			{% endif %}
			, id_order
			, null
		)
	)

