{% if time_grain == 'P1M' %} 
coalesce (1.0*sum(case when no_pause=0 then uvol end)
/(1.0*count(employee_code)/NULLIF(max(days_in_month), 0))
,0)

{% else %} 
coalesce (1.0*sum(case when no_pause=0 then uvol end)
/(1.0*count(employee_code)/7)
,0)


{% endif %}

{% if time_grain == 'P1M' %} 
1.0*count(employee_code)/max(days_in_month)

{% else %} 
1.0*count(employee_code)/7

{% endif %}

{% if from_dttm is not none %}

coalesce(1.0*count(employee_code)
/
('{{ to_dttm }}'::date - '{{ from_dttm }}'::date),0)

{% else %} 

coalesce(1.0*count(employee_code)
/
NULLIF(count(distinct date), 0),0)

{% endif %}

{% if time_grain == 'P1M' %} 
coalesce (1.0*sum(case when uvol=1
then uvol else 0 end)
/(NULLIF(1.0*count(id_courier)/max(days_in_month), 0)),0)

{% else %} 
coalesce (1.0*sum(case when uvol=1
then uvol else 0 end)
/(NULLIF(1.0*count(id_courier)/count (distinct date), 0)),0)

{% endif %}

NULLIF(AVG(IF(status_name = 'Успешно завершен'
and (id_partner_type = 5 AND id_partner NOT IN (24808,  49598,  22253,  60430,  54360)
), COALESCE(sum_paid, 0), NULL)), 0)

1.0*NULLIF(SUM(IF(status_name = 'Успешно завершен'
{% if (filter_values('name_partner'))  %} 
and name_partner in ({{ "'" + "','".join(filter_values('name_partner',remove_filter=True)) + "'" }})
{% else %}
AND (id_partner_type=4)
{% endif %} 
,COALESCE(sum_paid, 0), NULL)), 0)
/
NULLIF(SUM(IF(status_name = 'Успешно завершен', COALESCE(sum_paid, 0), NULL)), 0)

{% if time_grain == 'P1M' %} 
coalesce (1.0*sum(case when uvol=1
then uvol else 0 end)
/(NULLIF(1.0*count(id_courier)/max(days_in_month), 0)),0)

{% else %} 
coalesce (1.0*sum(case when uvol=1
then uvol else 0 end)
/(NULLIF(1.0*count(id_courier)/count (distinct date), 0)),0)

{% endif %}

COUNT(DISTINCT IIF(delivery_time > 20, COALESCE(id_general, id_order), NULL)) / NULLIF(CAST(COUNT(DISTINCT IIF(status_name_ = 'Успешно завершен', COALESCE(id_general, id_order), NULL)) AS NUMERIC), 0) * 1.0 - LEAD(COUNT(DISTINCT IIF(delivery_time > 20, COALESCE(id_general, id_order), NULL)) / NULLIF(CAST(COUNT(DISTINCT IIF(status_name_ = 'Успешно завершен', COALESCE(id_general, id_order), NULL)) AS NUMERIC), 0)) OVER (ORDER BY {% if filter_values('group_type')[0] == 'По месяцам'%}
  MonthYear
{% elif  filter_values('group_type')[0] == 'По неделям'%}
  number_week
{%else%}
  MonthYear
{% endif %} DESC)

