- LEAD(COUNT(DISTINCT IIF(DATEDIFF(MINUTE, date_supply, date_supply_until) - order_time < 0 AND status_name_ = 'Успешно завершен', COALESCE(id_general, id_order), NULL)) / NULLIF(CAST(COUNT(DISTINCT IIF(status_name_ = 'Успешно завершен', COALESCE(id_general, id_order), NULL)) as numeric), 0 ) ) OVER (ORDER BY {% if filter_values('group_type')[0] == 'По месяцам'%}
  MonthYear
{% elif  filter_values('group_type')[0] == 'По неделям'%}
  number_week
{%else%}
  MonthYear
{% endif %} DESC)

COUNT(DISTINCT IIF(status_name_ = 'Успешно завершен', COALESCE(id_general, id_order), NULL)) * 1.0 / NULLIF(LEAD(COUNT(DISTINCT IIF(status_name_ = 'Успешно завершен', COALESCE(id_general, id_order), NULL))) OVER (ORDER BY {% if filter_values('group_type')[0] == 'По месяцам'%}
  MonthYear
{% elif  filter_values('group_type')[0] == 'По неделям'%}
  number_week
{%else%}
  MonthYear
{% endif %} DESC), 0) - 1

( COUNT(DISTINCT IIF(delivery_time + time_done_from_start_list > 45, COALESCE(id_general, id_order), NULL)) 
/ NULLIF(CAST(COUNT(DISTINCT IIF(status_name_ = 'Успешно завершен', COALESCE(id_general, id_order), NULL)) AS NUMERIC),0) ) * 1.0 - LEAD(COUNT(DISTINCT IIF(delivery_time + time_done_from_start_list > 45, COALESCE(id_general, id_order), NULL))
/ NULLIF(CAST(COUNT(DISTINCT IIF(status_name_ = 'Успешно завершен', COALESCE(id_general, id_order), NULL)) AS NUMERIC),0) ) OVER (ORDER BY {% if filter_values('group_type')[0] == 'По месяцам'%}
  MonthYear
{% elif  filter_values('group_type')[0] == 'По неделям'%}
  number_week
{%else%}
  MonthYear
{% endif %} DESC)

{% if time_grain == 'P1M' %} 
coalesce (1.0*sum(case when uvol=1
then uvol else 0 end)
/(NULLIF(1.0*count(id_courier)/max(days_in_month), 0)),0)

{% else %} 
coalesce (1.0*sum(case when uvol=1
then uvol else 0 end)
/(NULLIF(1.0*count(id_courier)/count (distinct date), 0)),0)

{% endif %}

